//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
scwin.gDepCd = js_dep_cd;
scwin.gEmpNo = js_emp_no;
scwin.gLdMktTp = js_market;
scwin.gLastJob = "";
scwin.vScrenID = "ULDINS21401.xml";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.initPage = function() {
    scwin.fn_readGrntFee();
    var vAPPL_RSLT_CD = $c.stf.getObjectValue(txb_APPL_RSLT_CD);
    if (vAPPL_RSLT_CD != "R") {
        $c.stf.showObj(btn_Approv, false); // 승인버튼 숨기기.
        $c.stf.showObj(btn_REJECT, false);
        txa_reject_rsn.setReadOnly(true);
    }
    $c.stf.setObjectValue(txb_EMP_NO, js_emp_no); // 세션정보 넘기기. 

};
scwin.fn_readGrntFee = function() {
    var vTemp = frame.FrameID;
    var vROW = vTemp.split("=")[1];

    //alert("vROW : "+vROW);
    /*
    txb_ISUR_CD.value =  frame.Provider("../").dts_PassList.NameValue(vROW,"ISUR_CD");
    txb_COM_NM.value =  frame.Provider("../").dts_PassList.NameValue(vROW,"COM_NM");
    edt_APPL_DDTM.text =  frame.Provider("../").dts_PassList.NameValue(vROW,"APPL_DDTM");
    txb_STD_CD_APCT_ID.value =  frame.Provider("../").dts_PassList.NameValue(vROW,"STD_CD_APCT_ID");
    edt_STD_CD_GRNT_FEE_PACK_PAY_AMT.text =  frame.Provider("../").dts_PassList.NameValue(vROW,"STD_CD_GRNT_FEE_PACK_PAY_AMT");
    txb_CORP_USR_NM.value =  frame.Provider("../").dts_PassList.NameValue(vROW,"CORP_USR_NM");
    txb_BELNG_DEP_NM.value =  frame.Provider("../").dts_PassList.NameValue(vROW,"USR_BELNG_DEP_NM");
    txb_JOBTITL_NM.value =  frame.Provider("../").dts_PassList.NameValue(vROW,"JOBTITL_NM");
    txb_CELLPHONE_NO.value =  frame.Provider("../").dts_PassList.NameValue(vROW,"CELLPHONE_NO");
    txb_TEL_NO.value =  frame.Provider("../").dts_PassList.NameValue(vROW,"TEL_NO");
    txb_EMAIL.value =  frame.Provider("../").dts_PassList.NameValue(vROW,"EMAIL");
    txr_eject_rsn.text =  frame.Provider("../").dts_PassList.NameValue(vROW,"APPL_RSLT_PROCS_CONTN");
    */
    //납부공문요청일련번호-PK
    txb_PAY_OFCDOC_REQ_SEQ.setValue($c.frame.path("../").dts_PassList.getCellData(vROW, "PAY_OFCDOC_REQ_SEQ"));

    //alert("납부공문요청일련번호 : "+getObjectValue(txb_PAY_OFCDOC_REQ_SEQ));

    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneralForDynamicName" + "&outputMessageId=GRNTFEEAPPROVALLIST_21400_INOUT" + "&service=krx.lds.ins.listingcommon.services.ListingCommonApp" + "&queryId=lds.ins.etc.select.readGrntFeeApproval.dyn" + "&{P}PAY_OFCDOC_REQ_SEQ=" + $c.stf.getObjectValue(txb_PAY_OFCDOC_REQ_SEQ);
    dts_MASTER.DataID = encodeURI(url);
    dts_MASTER.Reset();
};
scwin.fn_HideDebugCtrls = function() {
    $c.stf.showObj(panel_debug, false);
};
scwin.fn_executeGrntFeeApproval = function(APPL_FLAG) {
    if (APPL_FLAG == "Y") {
        scwin.gLastJob = "승인";
    } else if (APPL_FLAG == "N") {
        if ($c.stf.getObjectValue(txa_reject_rsn) == "") {
            $c.win.alert($c.stf.getMessageParam("MSG-A005", "거부사유"));
            txa_reject_rsn.focus();
            return;
        }
        var vRejectRsn = $c.stf.getObjectValue(txa_reject_rsn);
        if ($c.stf.checkMaxLength(txa_reject_rsn, 200, '거부사유') == false) {
            return;
        }
        scwin.gLastJob = "거부";
    }
    $c.stf.setObjectValue(txb_APPL_RSLT_CD, APPL_FLAG);
    //	return;
    var msg = $c.stf.getMessageParam("MSG-A006", scwin.gLastJob);
    var res = window.confirm(msg);
    if (res) {
        trs_Save.Action = "/PrepayInfoAction.do?method=executeGrntFeeApproval" + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
        trs_Save.KeyName = "toinb_dataid4";
        trs_Save.KeyValue = "JSP(I:pInput=dts_MASTER)";
        trs_Save.Parameters = "EMP_NO=" + js_emp_no + ",EMP_NM=" + js_emp_nm + ",EMAIL=" + js_email;
        trs_Save.Post();
    }
};
scwin.dts_MASTER_OnLoadError = function() {
    $c.stf.alert_error(dts_MASTER);
};
scwin.dts_MASTER_OnLoadCompleted = function(rowcount) {
    //한글금액표기
    $c.stf.setObjectValue(txb_AmtHan, fn_ChgAmtToHan($c.stf.getObjectValue(edt_STD_CD_GRNT_FEE_PACK_PAY_AMT)));
};
scwin.trs_Save_OnFail = function() {
    var msg = $c.stf.getMessageParam("MSG-A002", scwin.gLastJob);
    $c.win.alert(msg);
    $c.stf.alert_error(trs_Save);
};
scwin.trs_Save_OnSuccess = async function() {
    var msg = $c.stf.getMessageParam("MSG-A001", scwin.gLastJob);
    $c.win.alert(msg);
    var fr_fn_Search = $c.frame.path("../").fn_listGrntFeeApproval;
    fr_fn_Search();
    await $c.frame.CloseFrame();
};
scwin.btn_Approv_onclick = function() {
    scwin.fn_executeGrntFeeApproval("Y");
};
scwin.btn_REJECT_onclick = function() {
    scwin.fn_executeGrntFeeApproval("N");
};
scwin.btn_Close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.gform_onload = function() {
    scwin.fn_HideDebugCtrls();

    //fn_SetCode();
    scwin.initPage();
};
